const ONE_WS = 1;
/** Two unmarked workspaces: no workspace can be chosen. */
const AMBIGUOUS = 2;
/** A client workspace plus the organisation's own, marked. */
const MARKED = 3;
/** No workspace at all. */
const NONE = 4;
const USER = 11;

